import numpy as np
def load(p):
    ls=open(p).read().splitlines(); n=int(ls[0]); s=[]; c=[]
    for l in ls[2:2+n]:
        t=l.split(); s.append(t[0]); c.append([float(x) for x in t[1:4]])
    return s,np.array(c)
sym,pos = load("work/final.xyz")
n=len(sym)
from collections import Counter
print("atom count:", n, Counter(sym))
# bonded-typology check via covalent radii
rcov={'H':0.32,'C':0.75,'N':0.71,'O':0.64,'F':0.60,'Cl':1.02,'Ge':1.22,'Au':1.37}
nb={i:[] for i in range(n)}
for i in range(n):
    for j in range(i+1,n):
        dd=np.linalg.norm(pos[i]-pos[j])
        if dd < 1.25*(rcov[sym[i]]+rcov[sym[j]]):
            nb[i].append(j); nb[j].append(i)
# expected coordination counts
issues=[]
for i in range(n):
    s=sym[i]; k=len(nb[i])
    if s=='H' and k!=1: issues.append((i,s,k))
    if s=='F' and k!=1: issues.append((i,s,k))
    if s=='C' and k not in (3,4): issues.append((i,s,k))
    if s=='N' and k!=3: issues.append((i,s,k))
    if s=='O' and k!=2: issues.append((i,s,k))
    if s=='Cl' and k!=1: issues.append((i,s,k))
    if s=='Ge' and k not in (5,6): issues.append((i,s,k))
    if s=='Au' and k!=2: issues.append((i,s,k))
print("coordination issues:", issues)
# every H accounted
print("H count:", sum(1 for s in sym if s=='H'))
# nonbonded clash check
clash=0
for i in range(n):
    for j in range(i+1,n):
        dd=np.linalg.norm(pos[i]-pos[j])
        if dd < 1.0 and j not in nb[i]:
            print("clash",sym[i],i,sym[j],j,round(dd,2)); clash+=1
print("nonbonded clashes:", clash)
# C-F, C-H, ring C-C samples
def d(i,j): return np.linalg.norm(pos[i]-pos[j])
print("sample C-F:", round(d(18,19),3), " ring C-N:", round(d(4,5),3), " ring C-C:", round(d(5,6),3), " C-H:", round(d(6,10),3))
